<?php $pageTitle='Contact | StudentHub'; require __DIR__.'/includes/header.php'; $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$message=trim($_POST['message']??'');if(strlen($name)<2||!$email||strlen($message)<5)$msg='Please enter a valid name, email and message.';else{$row=['name'=>$name,'email'=>$email,'message'=>$message,'created_at'=>date('c')];file_put_contents(__DIR__.'/storage/contact_messages.jsonl',json_encode($row,JSON_UNESCAPED_SLASHES).PHP_EOL,FILE_APPEND|LOCK_EX);$msg='Your message was recorded locally.';}} ?><span class="eyebrow">Get in touch</span><h1>Contact the StudentHub team</h1><?php if($msg): ?><p class="notice"><?= e($msg) ?></p><?php endif; ?><form class="form" method="post"><div class="field"><label for="name">Full name</label><input id="name" name="name" required minlength="2"></div><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" required></div><div class="field"><label for="message">Message</label><textarea id="message" name="message" rows="5" required minlength="5"></textarea></div><button class="button">Send message</button></form><?php require __DIR__.'/includes/footer.php'; ?>
